/**
 * social-milestone — follower/subscriber count rolling up to a milestone with celebration.
 *
 * Converted from Remotion FollowerMilestone. Counter rolls up to target number,
 * glow intensifies, then confetti burst + celebration badge pop on hit.
 *
 * Block structure (docs/blocks.md):
 *   background — SceneBackground (brand gradient / Pexels media + scrims)
 *   hero       — MilestoneBadge primitive (rolling number + glow + confetti
 *                + celebration pill)
 *   caption    — the uppercase label inside MilestoneBadge (no TemplateText)
 */

import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { resolveTokens } from "../theme";
import { SceneBackground, mediaBackgroundSchemaFields, mediaBackgroundDefaults } from "./scene-background";
import { stripPipe } from "../typography";
import { MilestoneBadge } from "../primitives/social/MilestoneBadge";

export const socialMilestoneSchema: Record<string, VariableField> = {
  label: {
    type: "string",
    label: "Label",
    default: "Followers",
    required: true,
    description: "Label above the number (e.g. Followers, Subscribers, Downloads)",
  },
  targetNumber: {
    type: "number",
    label: "Target number",
    default: 10000,
    required: true,
    description: "The milestone number to reach",
  },
  startNumber: {
    type: "number",
    label: "Start number",
    default: "",
    description: "Number the counter starts rolling from. Leave empty to auto-calculate (~98% of target).",
  },
  badgeText: {
    type: "string",
    label: "Badge text",
    default: "10K Followers!",
    description: "Celebration badge text that pops in at milestone",
  },
  badgeEmoji: {
    type: "string",
    label: "Badge emoji",
    default: "🎉",
    description: "Emoji shown in the celebration badge",
  },
  badgeColor: {
    type: "color",
    label: "Badge color",
    default: "#facc15",
    description: "Background color of the celebration badge",
  },
  ...mediaBackgroundSchemaFields,
};

export const socialMilestoneDefaults: Record<string, unknown> = {
  label: "Followers",
  targetNumber: 10000,
  startNumber: "",
  badgeText: "10K Followers!",
  badgeEmoji: "🎉",
  badgeColor: "#facc15",
  ...mediaBackgroundDefaults,
};

export const SocialMilestoneTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  beatIntensity,
  width,
  height,
  sceneDuration,
  isPlaying = true,
  backgroundEffect,
}) => {
  // Accent fallback migrated from the historical #3b82f6 to the canonical token.
  const { accent, font, explicit } = resolveTokens(style);

  const label = stripPipe(String(variables.label || "Followers"));
  const gradSeed = label.split("").reduce((acc: number, c: string) => acc + c.charCodeAt(0), 0);
  const targetNumber = Number(variables.targetNumber) || 10000;
  const rawStart = variables.startNumber != null ? Number(variables.startNumber) : undefined;
  const badgeText = stripPipe(String(variables.badgeText || "10K Followers!"));
  const badgeEmoji = String(variables.badgeEmoji || "🎉");

  // Media-mode legibility: when a Pexels photo/video is behind, MilestoneBadge
  // forces the label to full white and stacks a stronger drop-shadow on
  // number + label so they punch through busy footage. SceneBackground
  // already adds a vignette + bottom scrim. Mirrors bigNumber's treatment.
  const hasMedia = !!String(variables.mediaUrl || "").trim() &&
    String(variables.mediaType || "auto") !== "gradient";

  return (
    <div
      style={{
        width,
        height,
        backgroundColor: "#000",
        position: "relative",
        overflow: "hidden",
        fontFamily: font,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* [slot: background] Gradient background — supports Pexels media when mediaUrl is set */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        mediaUrl={String(variables.mediaUrl || "")}
        mediaType={String(variables.mediaType || "auto")}
        mediaPoster={String(variables.mediaPoster || "")}
        backgroundEffect={backgroundEffect}
        seed={gradSeed}
        isPlaying={isPlaying}
        beatIntensity={beatIntensity}
      />
      {/* [slot: hero] Rolling counter + label + confetti + celebration pill —
          shared primitive (owns the milestone timing windows) */}
      <MilestoneBadge
        progress={progress}
        width={width}
        height={height}
        targetNumber={targetNumber}
        label={label}
        startNumber={rawStart}
        badgeText={badgeText}
        badgeEmoji={badgeEmoji}
        accent={accent}
        hasMedia={hasMedia}
        muted={explicit.muted}
        beatIntensity={beatIntensity}
        confettiBgColor={style.brandKit?.secondary}
      />
    </div>
  );
};

/**
 * MilestoneBadge — numeric achievement badge with rolling counter, glow,
 * confetti burst, and celebration pill.
 *
 * The
 * template composes this component, so the two can no longer drift.
 * The primitive owns:
 *   - the big rolling number with auto-fit font scale
 *   - the uppercase label above
 *   - the radial glow that ramps up as the count nears target
 *   - the confetti burst (via shared ConfettiLayer) that fires on hit
 *   - the celebration pill ("🎉 10K Followers!") that pops in on hit
 *
 * It does NOT own the SceneBackground gradient/media — that stays in the
 * scene composer so the same badge can render over brand gradient or
 * Pexels footage.
 *
 * Distinct from CountUpNumber: this primitive has badge framing
 * (label + pill + confetti) baked in.
 *
 * Props:
 *  - progress        — scene progress 0..1
 *  - width / height  — frame dimensions
 *  - targetNumber    — milestone to reach
 *  - label           — uppercase label above the number (e.g. "Followers")
 *  - prefix / suffix — optional decoration around the number (e.g. "$", "+", "K")
 *  - startNumber     — counter origin. Defaults to ~98% of target so it
 *                      always rolls UP visibly.
 *  - badgeText       — celebration pill text (e.g. "10K Followers!")
 *  - badgeEmoji      — emoji shown in the pill (default 🎉)
 *  - badgeColor      — kept for API parity with the source schema
 *                      (the pill itself uses a translucent dark fill so
 *                      it reads on any background)
 *  - accent          — brand accent driving the glow color (default "#00e5a0")
 *  - hasMedia        — when true, use the media-safe text treatment
 *                      (full white label + drop shadows). Defaults to false.
 *  - muted           — explicit brand-kit muted color for the label
 *                      (gradient mode only; media mode forces white).
 *  - beatIntensity   — optional 0..1 audio reactivity (subtle scale pop)
 *  - confettiBgColor — optional confetti hue-filter input (parity with source)
 */

import * as React from "react";
import {
  interpolate,
  spring,
  SPRING_SMOOTH,
  SPRING_BOUNCY,
} from "../../motion";
import { withOpacity } from "../../theme";
import { stripPipe } from "../../typography";
import { Emoji } from "../../emoji";
import { renderWithEmoji } from "../../emoji/emoji-text";
import { ConfettiLayer } from "../../scene-templates/confetti-layer";
import { TOKEN_DEFAULTS } from "../../theme";

const CLAMP = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

export interface MilestoneBadgeProps {
  progress: number;
  width: number;
  height: number;
  targetNumber: number;
  label: string;
  prefix?: string;
  suffix?: string;
  startNumber?: number;
  badgeText?: string;
  badgeEmoji?: string;
  badgeColor?: string;
  accent?: string;
  hasMedia?: boolean;
  /** Explicit brand-kit muted color for the label (gradient mode). */
  muted?: string;
  beatIntensity?: number;
  confettiBgColor?: string;
}

export const MilestoneBadge: React.FC<MilestoneBadgeProps> = ({
  progress,
  width,
  height,
  targetNumber,
  label: rawLabel,
  prefix = "",
  suffix = "",
  startNumber,
  badgeText: rawBadgeText = "",
  badgeEmoji = "🎉",
  accent = TOKEN_DEFAULTS.accent,
  hasMedia = false,
  muted,
  beatIntensity = 0,
  confettiBgColor,
}) => {
  const dim = Math.min(width, height);
  const s = dim / 1080;

  const label = stripPipe(rawLabel || "");
  const badgeText = stripPipe(rawBadgeText || "");

  const safeTarget = Number.isFinite(targetNumber) ? targetNumber : 0;
  const safeStart =
    startNumber != null && Number.isFinite(startNumber)
      ? startNumber
      : Math.max(0, Math.round(safeTarget * 0.98));

  const labelColor = hasMedia ? "#ffffff" : (muted || "rgba(255,255,255,0.8)");
  const mediaTextShadow = hasMedia
    ? "0 2px 8px rgba(0,0,0,0.55), 0 6px 16px rgba(0,0,0,0.35)"
    : undefined;

  // ── Timing (mirror social-milestone source) ────────────────────
  // Counter rolls from progress 0.056 to 0.556
  const followerCount = Math.round(
    interpolate(progress, [0.056, 0.556], [safeStart, safeTarget], CLAMP),
  );
  const hasHitTarget = followerCount >= safeTarget;

  const numberScale = spring(
    interpolate(progress, [0, 0.25], [0, 1], CLAMP),
    SPRING_SMOOTH,
  );
  const glowIntensity = interpolate(progress, [0.33, 0.556], [0, 1], CLAMP);
  const labelOpacity = interpolate(progress, [0, 0.167], [0, 1], CLAMP);

  const badgeP = hasHitTarget
    ? spring(
        interpolate(progress, [0.556, 0.85], [0, 1], CLAMP),
        SPRING_BOUNCY,
      )
    : 0;
  const badgeScale = interpolate(badgeP, [0, 0.5, 1], [0, 1.2, 1], CLAMP);
  const badgeOpacity = badgeP;

  const confettiActive = hasHitTarget;
  const confettiProgress = confettiActive
    ? Math.max(0, (progress - 0.556) / 0.444)
    : 0;

  const beatScale = 1 + beatIntensity * 0.02;

  const numberDisplay = `${prefix}${followerCount.toLocaleString()}${suffix}`;
  // Auto-scale thresholds match social-milestone (the tuned source of truth).
  const fontSize =
    numberDisplay.length > 9
      ? dim * 0.09
      : numberDisplay.length > 6
        ? dim * 0.12
        : dim * 0.16;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Confetti — shared 200-particle layer, fires on milestone hit */}
      {confettiActive && (
        <ConfettiLayer
          progress={confettiProgress}
          width={width}
          height={height}
          beatIntensity={beatIntensity}
          bgColor={hasMedia ? undefined : confettiBgColor || accent}
        />
      )}

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: dim * 0.015,
          transform: `scale(${numberScale * beatScale})`,
          position: "relative",
          zIndex: 1,
          width: "100%",
        }}
      >
        {/* Label */}
        {label && (
          <div
            style={{
              color: labelColor,
              fontSize: dim * 0.032,
              fontWeight: 500,
              textTransform: "uppercase",
              letterSpacing: dim * 0.004,
              opacity: labelOpacity,
              textAlign: "center",
              ...(mediaTextShadow ? { textShadow: mediaTextShadow } : {}),
            }}
          >
            {label}
          </div>
        )}

        {/* Big number */}
        <div
          style={{
            color: "#ffffff",
            fontSize,
            fontWeight: 800,
            letterSpacing: dim * -0.004,
            lineHeight: 1,
            position: "relative",
            maxWidth: "90%",
            textAlign: "center",
            ...(mediaTextShadow ? { textShadow: mediaTextShadow } : {}),
          }}
        >
          {/* Glow behind number */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
              width: dim * 0.5,
              height: dim * 0.2,
              borderRadius: "50%",
              background: `radial-gradient(ellipse, ${withOpacity(accent, glowIntensity * 0.2)} 0%, ${withOpacity(accent, glowIntensity * 0.05)} 50%, transparent 70%)`,
              pointerEvents: "none",
            }}
          />
          <span style={{ position: "relative" }}>{numberDisplay}</span>
        </div>

        {/* Celebration badge */}
        {badgeText && (
          <div
            style={{
              position: "absolute",
              top: "100%",
              left: "50%",
              transform: `translateX(-50%) scale(${badgeScale})`,
              opacity: badgeOpacity,
              backgroundColor: "rgba(0,0,0,0.3)",
              border: "1px solid rgba(255,255,255,0.15)",
              borderRadius: 100 * s,
              padding: `${dim * 0.015}px ${dim * 0.037}px`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: dim * 0.011,
              whiteSpace: "nowrap",
              marginTop: dim * 0.02,
            }}
          >
            <Emoji char={badgeEmoji} size={dim * 0.045} verticalAlign="middle" />
            <span
              style={{
                color: "#ffffff",
                fontSize: dim * 0.036,
                fontWeight: 700,
                letterSpacing: dim * 0.0005,
              }}
            >
              {renderWithEmoji(badgeText, dim * 0.036)}
            </span>
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * confetti-layer — reusable confetti burst layer.
 *
 * Extracted from bg-confetti.tsx so any host template can compose the same
 * physics on top of its own backdrop. Used by:
 *  - bg-confetti.tsx (the standalone celebration template — gradient bg)
 *  - bg-media.tsx     (conditional via the `confetti` boolean — confetti
 *    layered over photo / video / gradient)
 *
 * Physics: 200 particles, even angular fan-out (360°) from center.
 * Particles move RADIALLY outward — both x and y follow the burst angle so
 * each particle exits the frame in its launch direction (top, sides, bottom
 * corners). A very gentle gravity tugs them slightly downward over time so
 * the motion still reads as natural, but it's never strong enough to reverse
 * an upward trajectory before the particle exits the frame. 3D tumble
 * approximated via scaleX flip. Progress-driven — deterministic for export.
 */

import React from "react";

const PARTICLE_COUNT = 200;

// Confetti palette spans the full hue wheel; filtered at runtime to drop any
// color too close in hue to the background (and would disappear).
const COLORS = ["#ef4444", "#ff6b6b", "#f97316", "#fb923c", "#ffd93d", "#34d399", "#6bcbff", "#818cf8", "#a78bfa", "#f472b6", "#ffffff"];

function seededRandom(seed: number): number {
  const x = Math.sin(seed * 12.9898 + seed * 78.233) * 43758.5453;
  return x - Math.floor(x);
}

/** Outward sweep — softer ease-out quad. Less front-loaded than cubic so
 *  the burst reads as a graceful arc rather than an explosion-and-stop. */
function easeOutQuad(p: number): number {
  return 1 - (1 - p) * (1 - p);
}

function hexHue(hex: string): number {
  const r = parseInt(hex.slice(1, 3), 16) / 255;
  const g = parseInt(hex.slice(3, 5), 16) / 255;
  const b = parseInt(hex.slice(5, 7), 16) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  if (d === 0) return 0;
  let h = 0;
  if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
  else if (max === g) h = ((b - r) / d + 2) / 6;
  else h = ((r - g) / d + 4) / 6;
  return h * 360;
}

function hueDistance(a: number, b: number): number {
  const d = Math.abs(a - b) % 360;
  return d > 180 ? 360 - d : d;
}

export interface ConfettiLayerProps {
  progress: number;
  width: number;
  height: number;
  beatIntensity?: number;
  /**
   * Optional background tone for hue-filtering. When provided, palette
   * colors within 35° of this hue are dropped so confetti doesn't blend
   * into a same-hue gradient. Pass the bg's dominant color (typically
   * secondary or accent). Omit for media-bg cases (photos/videos have no
   * single dominant color); the full palette will be used.
   */
  bgColor?: string;
}

export const ConfettiLayer: React.FC<ConfettiLayerProps> = ({
  progress,
  width,
  height,
  beatIntensity = 0,
  bgColor,
}) => {
  const s = Math.min(width, height) / 1080;
  /* Radial burst — each particle flies out in its launch direction until
   * it leaves the frame. Reach is sized off the LONG edge so even
   * particles aimed along the long axis (top/bottom in portrait, sides
   * in landscape) clear the frame edge by progress=1. Half-diagonal of
   * a 9:16 frame ≈ 0.61 * longEdge, so 0.95 gives ~35% headroom past
   * the corner — particles exit cleanly with a few hundred px of trail. */
  const BURST_RADIUS = Math.max(width, height) * 0.95;

  // Filter palette only if a bgColor is provided (gradient context). Over
  // photos/videos we keep the full palette since there's no single bg hue.
  let allColors = COLORS;
  if (bgColor) {
    const bgHue = hexHue(bgColor);
    const filtered = COLORS.filter(c => c === "#ffffff" || hueDistance(hexHue(c), bgHue) > 35);
    if (filtered.length >= 4) allColors = filtered;
  }

  return (
    <>
      {Array.from({ length: PARTICLE_COUNT }, (_, i) => {
        const seed = i + 1;

        // Even angular distribution — single biggest "feel" win vs random.
        const angle = (i / PARTICLE_COUNT) * Math.PI * 2;

        // Per-particle variance
        const forceFactor    = 0.75 + seededRandom(seed * 1) * 0.5;   // 0.75..1.25
        const durationFactor = 1.1  + seededRandom(seed * 3) * 0.6;   // 1.1..1.7 — slow arc
        const color          = allColors[i % allColors.length];
        const isCircle       = seededRandom(seed * 4) > 0.85;
        const startRot       = seededRandom(seed * 5) * 360;
        const rotSpeed       = (seededRandom(seed * 6) - 0.5) * 1440;
        const flipSpeed      = 3 + seededRandom(seed * 7) * 4;
        const flipPhase      = seededRandom(seed * 8) * Math.PI * 2;
        const widthFactor    = 0.45 + seededRandom(seed * 9) * 0.6;
        const heightFactor   = 0.7  + seededRandom(seed * 10) * 0.6;

        const p = Math.min(1, progress / durationFactor);

        // Radial burst — particles fly outward in their launch direction.
        // Outward distance eases out so they decelerate slightly near the
        // frame edge but don't reverse. A small quadratic gravity term tugs
        // them downward over time without overriding upward velocity before
        // they exit the frame.
        const reach   = BURST_RADIUS * forceFactor;
        const radialP = easeOutQuad(p);
        const gravity = height * 0.08 * p * p;
        const x = width * 0.5 + Math.cos(angle) * reach * radialP;
        const y = height * 0.5 + Math.sin(angle) * reach * radialP + gravity;

        const flip = Math.cos(p * Math.PI * flipSpeed + flipPhase);
        const rot  = startRot + rotSpeed * p;

        const baseSize = (8 + seededRandom(seed * 11) * 10) * s;
        const w = baseSize * widthFactor;
        const h = isCircle ? w : baseSize * heightFactor;

        const popScale = Math.min(1, p * 30);
        const opacity = p < 0.85 ? 1 : Math.max(0, 1 - (p - 0.85) / 0.15);
        const beatPulse = 1 + beatIntensity * 0.15;

        if (opacity <= 0) return null;
        if (y > height + 120 || y < -120 || x < -120 || x > width + 120) return null;

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x - w / 2,
              top: y - h / 2,
              width: w,
              height: h,
              borderRadius: isCircle ? "50%" : 1,
              backgroundColor: color,
              opacity,
              transform: `rotate(${rot}deg) scaleX(${flip}) scale(${popScale * beatPulse})`,
              pointerEvents: "none",
            }}
          />
        );
      })}
    </>
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};

/**
 * SceneBackground — shared backdrop component for any scene template that
 * wants to support both a brand-color gradient and stock media (Pexels
 * photo / video) as an alternate atmosphere.
 *
 * Usage:
 *   <SceneBackground
 *     style={style}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     mediaUrl={String(variables.mediaUrl || "")}
 *     mediaType={String(variables.mediaType || "auto")}
 *     seed={String(variables.texts || "")}
 *     isPlaying={isPlaying}
 *   />
 *   ... template's content layered on top
 *
 * Behavior:
 *   - Brand gradient is the always-on backdrop (uses BrandGradientOverlay).
 *   - When mediaUrl is set and mediaType isn't "gradient", the photo/video
 *     covers the gradient. Vignette + bottom-half darken give the content
 *     contrast against busy footage.
 *   - mediaType="gradient" deliberately ignores mediaUrl and renders only
 *     the brand gradient. First-class atmospheric mode.
 *   - When mediaUrl is empty / 404s / Pexels search returned nothing,
 *     gradient shows through cleanly (matches every other gradient-backed
 *     template).
 *
 * Extracted from bg-media.tsx so any template can compose it. bg-media
 * now uses this component too — its "media is the scene" identity comes
 * from how it positions the title (centered, full-frame), not from
 * duplicated render logic.
 */

import React, { useEffect, useRef } from "react";
import type { GlobalStyle, VariableField } from "../video-config";
import { BrandGradientOverlay } from "../backgrounds";
import { getBackgroundTransform } from "../backgrounds";

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov", ".m4v", ".avi"];

function isVideoUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => pathname.endsWith(ext));
  } catch {
    const lower = url.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
  }
}

export type ResolvedMediaType = "photo" | "video" | "gradient";

export function resolveMediaType(
  mediaType: string,
  mediaUrl: string,
): ResolvedMediaType {
  if (mediaType === "gradient") return "gradient";
  if (mediaType === "video") return "video";
  if (mediaType === "photo") return "photo";
  // "auto" — detect from URL extension
  return mediaUrl && isVideoUrl(mediaUrl) ? "video" : "photo";
}

/**
 * Standard schema fields any template can spread into its variableSchema
 * to enable media backgrounds. Keeps the field set + descriptions
 * consistent across templates.
 */
export const mediaBackgroundSchemaFields: Record<string, VariableField> = {
  mediaUrl: {
    type: "media",
    label: "Background media",
    description: "Optional photo or video URL behind this scene. When set, replaces the brand gradient.",
  },
  mediaKeyword: {
    type: "string",
    label: "Background search keyword",
    default: "",
    description: "2-4 word English term for Pexels stock-footage search (auto-fills mediaUrl).",
  },
  mediaType: {
    type: "enum",
    label: "Background media type",
    default: "auto",
    description: "auto detects photo/video from URL. 'gradient' is a deliberate mode — atmospheric brand-color scene with no stock footage.",
    options: ["auto", "photo", "video", "gradient"],
  },
  mediaPoster: {
    type: "string",
    label: "Background poster image",
    default: "",
    description: "Still image URL shown while a video backdrop is decoding its first frame. Auto-filled from Pexels' thumbnail when fillPexelsUrls sets a video mediaUrl. Hides the gradient flash that would otherwise appear in the ~50–400ms gap between a <video> mounting and decoding its first frame.",
  },
};

/** Default values for the media-background fields. Spread into a template's defaults. */
export const mediaBackgroundDefaults: Record<string, unknown> = {
  mediaUrl: "",
  mediaKeyword: "",
  mediaType: "auto",
  mediaPoster: "",
};

export interface SceneBackgroundProps {
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  width: number;
  height: number;
  mediaUrl?: string;
  mediaType?: string;
  /** Still image URL shown while the <video> backdrop decodes its first
   *  frame. Without it the element renders transparent during the
   *  ~50–400ms decode window and the gradient flashes through. */
  mediaPoster?: string;
  /** Background motion effect (drift / pulse / Ken Burns). Applied to the photo/video. */
  backgroundEffect?: string;
  /** Stable seed for the gradient breathing animation. Pass the scene's
   *  text content (or any stable string) — it's hashed deterministically. */
  seed?: number | string;
  /** Pause video when preview is paused. Defaults to true (export path). */
  isPlaying?: boolean;
  beatIntensity?: number;
}

export const SceneBackground: React.FC<SceneBackgroundProps> = ({
  style,
  progress,
  sceneDuration,
  width: _width,  // accepted for symmetry; not currently used in render
  height,
  mediaUrl = "",
  mediaType = "auto",
  mediaPoster,
  backgroundEffect,
  seed,
  isPlaying = true,
  beatIntensity = 0,
}) => {
  void _width;
  const resolved = resolveMediaType(mediaType, mediaUrl);
  const showMedia = resolved !== "gradient" && !!mediaUrl;

  const gradSeed = typeof seed === "number"
    ? seed
    : typeof seed === "string"
      ? seed.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0)
      : 0;

  const bgTransform = getBackgroundTransform(backgroundEffect, progress, beatIntensity);

  // Video playback control — same pause/seek logic bg-media used pre-extract.
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastProgress = useRef(progress);
  const videoStarted = useRef(false);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    if (!isPlaying) {
      vid.pause();
      videoStarted.current = false;
      return;
    }
    const progressChanged = Math.abs(progress - lastProgress.current) > 0.001;
    lastProgress.current = progress;
    if (progressChanged && !videoStarted.current) {
      vid.playbackRate = 1;
      vid.currentTime = 0;
      vid.play().catch(() => {});
      videoStarted.current = true;
    } else if (!progressChanged && videoStarted.current) {
      vid.pause();
      videoStarted.current = false;
    }
  }, [progress, isPlaying]);

  // Release the decoder on unmount. Without this, iOS Safari keeps the
  // video's decoder buffer alive after the React node is gone — each
  // scene transition (or play/pause/play cycle that remounts the active
  // scene) leaks one decoder, eventually crossing the renderer's memory
  // ceiling and triggering "A problem repeatedly occurred." Same recipe
  // as #409's CanvasPreview preload cleanup: pause → clear src → load().
  // Capture the ref at mount-time so the cleanup uses the same node we
  // mounted (the ref's .current is stale by unmount).
  useEffect(() => {
    const vid = videoRef.current;
    return () => {
      if (!vid) return;
      vid.pause();
      vid.removeAttribute("src");
      vid.load();
    };
  }, []);

  return (
    <>
      <BrandGradientOverlay
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        seed={gradSeed}
      />

      {showMedia && (resolved === "video" ? (
        <video
          ref={videoRef}
          src={mediaUrl}
          // Poster paints during the decode window so the user sees the
          // (still) first frame instead of a transparent <video> letting
          // the brand gradient show through. Pexels returns a thumbnail
          // image alongside each video; fillPexelsUrls stores it in
          // `variables.mediaPoster`. Layered defense alongside preload="auto"
          // below: on desktop the byte preloader makes decode fast, on
          // mobile (where the preloader skips video pre-mounting to dodge
          // the iOS Safari memory crash) the poster is the primary shield.
          poster={mediaPoster || undefined}
          muted
          loop
          playsInline
          // preload="auto" — without it, browsers default to "metadata":
          // they only load the container/dimensions, not the byte stream
          // needed to decode frames. The element then renders transparent
          // until the first decoded frame arrives, letting the brand
          // gradient flash through whenever a scene mid-playback transitions
          // to a media backdrop. The parent preloader caches the bytes, but
          // decoder state is per-element, so the active mount still has to
          // decode the first frame; "auto" kicks that work off the instant
          // the element mounts.
          preload="auto"
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
          }}
        />
      ) : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
            backgroundImage: `url(${mediaUrl})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
      ))}

      {showMedia && (
        <>
          {/* Vignette — gives the content contrast against busy footage. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.55) 80%, rgba(0,0,0,0.75) 100%)",
              pointerEvents: "none",
            }}
          />
          {/* Center-text scrim — soft elliptical darken where headlines /
              wordStagger words / metrics typically land. Subtle (max ~22%
              darken at the focal point) so the photo still reads bright at
              the edges, but text on busy bg gets reliable contrast without
              relying on heavier shadows. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse 85% 50% at 50% 50%, rgba(0,0,0,0.22) 0%, rgba(0,0,0,0.10) 50%, transparent 80%)",
              pointerEvents: "none",
            }}
          />
          {/* Bottom-half darken — improves text readability on photos. */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: height * 0.45,
              background:
                "linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 100%)",
              pointerEvents: "none",
            }}
          />
        </>
      )}
    </>
  );
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares what variables it needs (auto-shown as input fields in the Studio)
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "../theme";
import type { GlobalStyle, VariableField, SafeZone } from "../video-config";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: GlobalStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

/**
 * What a template can DO inside a video. A template can serve more than
 * one job — `bigNumber` is `["claim", "proof"]`; `media` is
 * `["atmosphere", "setup"]`. Used by the chat composer to pick templates
 * by scene-job rather than by the (less useful) category bucket.
 *
 * - `setup` — opens the world, names the subject, frames the question
 * - `claim` — makes a falsifiable statement the rest of the video earns
 * - `proof` — backs a claim with a number, quote, mockup, code, or chart
 * - `atmosphere` — breathing room; ties scenes together visually
 * - `payoff` — punchline, reveal, or satisfying answer to an earlier setup
 * - `punctuation` — short energy beat that breaks pattern or lands a joke
 * - `ask` — pushes the viewer to the next action; closer-territory only
 */
export type TemplateJob = "setup" | "claim" | "proof" | "atmosphere" | "payoff" | "punctuation" | "ask";

/**
 * The visual register a template lives in — what the *viewer* notices
 * before reading any copy. The chat's diversity rule reads this rather
 * than `category` because two `card-led` bodies look the same to the
 * viewer even when they're a `testimonial` and a `bigNumber`.
 *
 * - `motion-led` — animation IS the content (confetti, emoji rain, charts)
 * - `typography-led` — text fills the frame (bigNumber, ctaLogo, tripleStats)
 * - `device-led` — phone/browser/terminal frame is the focal element
 * - `card-led` — quote/feature/comparison cards
 * - `mockup-led` — full UI surface (chat thread, search results, app feed)
 */
export type TemplateRegister =
  | "motion-led"
  | "typography-led"
  | "device-led"
  | "card-led"
  | "mockup-led";

/**
 * A registered scene template.
 */
export interface SceneTemplate {
  id: string;
  /** Built-in templates leave these blank — DB owns them. Vibecoded
   *  templates carry their own here since they have no DB row. */
  label?: string;
  description?: string;
  category?: string | null;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  /** Thumbnail URL for visual picker (optional) */
  thumbnail?: string;
  /** If true, template consumes the video-level defaultTextArchetype */
  usesGlobalTextEffect: boolean;
  /** If true, template uses the video-level defaultTransition */
  usesGlobalTransition: boolean;
  /** If true, template uses the video-level defaultBackgroundEffect */
  usesGlobalBackgroundEffect: boolean;
  /**
   * Spatial budget for text effects.
   * - "tight" (default): text shares the frame with UI (mockup, chart). Expressive
   *   effects are auto-clamped to contained equivalents to prevent clipping.
   * - "open": text is the focal element (bg-* templates). All effects allowed.
   */
  textCanvas?: "tight" | "open";
  /**
   * Hard input gates — what this template needs from the user's input to fire
   * legitimately. The AI uses these to filter out templates that would force
   * it to invent content (e.g. \`bigNumber\` without a real number).
   *
   * Set to true when the template's value depends on input that the model
   * can't fabricate honestly: a stat, a quote, an uploaded screenshot.
   * Defaults to false (no constraint).
   */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  /** Template can be backed by Pexels stock footage (e.g. \`media\`). */
  allowsStockMedia?: boolean;
  /** Variable schema — Studio auto-generates inputs from this */
  variableSchema: Record<string, VariableField>;
  /** Default values for all variables */
  defaultVariables: Record<string, unknown>;
  /** Minimum scene duration in seconds */
  minDuration?: number;
  /** Recommended scene duration in seconds */
  preferredDuration?: number;
  /** The React component that renders this template */
  component: React.FC<SceneTemplateProps>;
}

/**
 * Serializable template metadata (no component) — for edge functions, API, MCP.
 */
export interface SceneTemplateMetadata {
  id: string;
  usesGlobalTextEffect: boolean;
  usesGlobalTransition: boolean;
  usesGlobalBackgroundEffect: boolean;
  textCanvas?: "tight" | "open";
  /** Hard input gates — see SceneTemplate.requiresStat etc. */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  allowsStockMedia?: boolean;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  variableSchema: Record<string, VariableField>;
  defaultVariables: Record<string, unknown>;
  minDuration?: number;
  preferredDuration?: number;
}
